args.command:
python3 -c "import numpy as np; import scipy.optimize as opt; 
def f(x, phi): return 5*np.cos(x) - np.cos(5*x + phi)
def max_f(phi):
    res = opt.minimize_scalar(lambda x: -f(x, phi), bounds=(0, 2*np.pi), method='bounded')
    return -res.fun

phi_vals = np.linspace(0, 2*np.pi, 100)
max_vals = [max_f(p) for p in phi_vals]
print(f'Min max_f: {min(max_vals)} at phi: {phi_vals[np.argmin(max_vals)]}')
print(f'max_f(0): {max_f(0)}')
print(f'max_f(np.pi): {max_f(np.pi)}')"

