args.command:
python3 -c "import numpy as np; 
def f(x, phi): return 5*np.cos(x) - np.cos(5*x + phi)
def get_max(phi):
    x_vals = np.linspace(0, 2*np.pi, 2000)
    return np.max([f(x, phi) for x in x_vals])

phi_vals = np.linspace(0, 2*np.pi, 100)
results = [(p, get_max(p)) for p in phi_vals]
best_phi, min_max = min(results, key=lambda x: x[1])
print(f'Best phi approx: {best_phi}, Min Max: {min_max}')
print(f'Max at phi=0: {get_max(0)}')
print(f'Max at phi=pi: {get_max(np.pi)}')"

